-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'BANCO DE DADOS' and a.numero = 2
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 2 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 02', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 02 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/BANCO-DE-DADOS/ATIVIDADES/ATIVIDADE-PRATICA-AULA-02.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Cite três características que diferenciam um gerenciador de outro.', 0.2, 'Três entre: **modelo de dados**, **licença**, **transações ACID**, **desempenho**, **escalabilidade**, **segurança**, **ferramentas e comunidade**.', 'Nota cheia (0,2): três características corretas. Metade (0,1): duas corretas. Zero (0): uma ou nenhuma.'),
      (v_atividade, 1, 2, 'Explique duas dessas características com um exemplo do sistema da clínica.', 0.4, 'Exemplos: **segurança** — a clínica guarda dados de saúde e precisa de usuários e permissões por setor; **transações ACID** — agendamento e pagamento da consulta salvos juntos; **desempenho** — buscar o histórico do paciente rapidamente; **modelo de dados** — tabelas de pacientes, médicos e consultas.', 'Palavras-chave: duas características explicadas + exemplo da clínica. Nota cheia (0,4): duas explicadas com exemplo coerente. Metade (0,2): uma explicada com exemplo, ou duas sem exemplo. Zero (0): características erradas ou sem relação com a clínica.'),
      (v_atividade, 1, 3, 'Explique por que a licença do gerenciador deve ser considerada pela clínica.', 0.4, 'A licença define o **custo** (gratuita ou paga) e o **que é permitido** (uso comercial, suporte). Um gerenciador **livre** (ex.: PostgreSQL) reduz custos; um **comercial** (ex.: Oracle) pode ter custo alto de licença e suporte.', 'Palavras-chave: custo; permissões de uso/suporte; exemplo livre × comercial. Nota cheia (0,4): custo + o que é permitido ou exemplo. Metade (0,2): só "custa dinheiro". Zero (0): sem relação com licença.'),
      (v_atividade, 2, 1, 'Diga o que é uma transação num banco de dados.', 0.2, '**Conjunto de comandos que deve acontecer inteiro ou nada** (tudo ou nada).', 'Nota cheia (0,2): ideia de conjunto + tudo ou nada. Metade (0,1): "um comando no banco" sem a ideia de tudo ou nada. Zero (0): confunde com backup ou pagamento.'),
      (v_atividade, 2, 2, 'Explique qual propriedade ACID evita "pagamento sem pedido" e como ela funciona nessa compra.', 0.4, '**Atomicidade**: pagamento e gravação do pedido ficam na **mesma transação**; se uma parte falha, **nada é confirmado** e o banco volta ao estado anterior, então não fica pagamento sem pedido.', 'Palavras-chave: atomicidade; mesma transação; tudo ou nada; desfaz. Nota cheia (0,4): nome + funcionamento na compra. Metade (0,2): só o nome, ou explicação sem o nome. Zero (0): outra propriedade sem explicação coerente.'),
      (v_atividade, 2, 3, 'Explique o papel dos comandos COMMIT e ROLLBACK nessa situação.', 0.4, '**COMMIT** confirma tudo quando pagamento e pedido deram certo; **ROLLBACK** desfaz tudo se algo falhar (como a queda do servidor antes do fim), deixando o banco como estava.', 'Palavras-chave: COMMIT confirma; ROLLBACK desfaz. Nota cheia (0,4): os dois comandos explicados na situação. Metade (0,2): só um explicado. Zero (0): funções trocadas.'),
      (v_atividade, 3, 1, 'Escreva o nome das quatro propriedades da sigla ACID.', 0.2, '**Atomicidade, Consistência, Isolamento e Durabilidade.**', 'Nota cheia (0,2): as quatro. Metade (0,1): três. Zero (0): duas ou menos.'),
      (v_atividade, 3, 2, 'Dê um exemplo do app de ingressos para Isolamento e outro para Consistência.', 0.4, '**Isolamento:** duas pessoas comprando o último ingresso ao mesmo tempo não vendem o mesmo lugar duas vezes. **Consistência:** o número de ingressos vendidos nunca passa da capacidade do show (regra respeitada).', 'Nota cheia (0,4): dois exemplos coerentes. Metade (0,2): um exemplo coerente. Zero (0): exemplos trocados ou sem relação.'),
      (v_atividade, 3, 3, 'Dê um exemplo para Durabilidade e explique o que aconteceria sem ela.', 0.4, '**Durabilidade:** depois de confirmada a compra, o ingresso continua registrado mesmo se o servidor cair em seguida. Sem ela, o cliente **pagaria e perderia o ingresso** depois de uma queda de energia.', 'Nota cheia (0,4): exemplo + consequência. Metade (0,2): só um dos dois. Zero (0): confunde com outra propriedade.'),
      (v_atividade, 4, 1, 'Diga o que é escalabilidade de um gerenciador.', 0.2, 'Capacidade de o gerenciador **aguentar crescer** (mais dados e mais acessos) mantendo o desempenho.', 'Nota cheia (0,2): crescer + manter funcionamento/desempenho. Metade (0,1): só "ficar maior". Zero (0): sem relação.'),
      (v_atividade, 4, 2, 'Explique a diferença entre escalabilidade vertical e horizontal com um exemplo para a loja.', 0.4, '**Vertical:** aumentar os recursos do **mesmo servidor** (mais memória, processador melhor). **Horizontal:** acrescentar **mais servidores** para dividir a carga (ex.: servidores de leitura nas promoções).', 'Nota cheia (0,4): as duas diferenciadas com exemplo da loja. Metade (0,2): diferença certa sem exemplo, ou só uma explicada. Zero (0): conceitos trocados.'),
      (v_atividade, 4, 3, 'Cite um recurso do gerenciador que melhora o desempenho das consultas e explique como ele ajuda.', 0.4, '**Índices** (ou otimizador de consultas, cache): o índice funciona como o índice de um livro, permitindo achar as linhas **sem ler a tabela inteira**, o que deixa a consulta mais rápida.', 'Nota cheia (0,4): recurso correto + como ajuda. Metade (0,2): recurso sem explicação. Zero (0): recurso sem relação com desempenho.'),
      (v_atividade, 5, 1, 'Diga o modelo de dados de cada um dos quatro gerenciadores.', 0.2, 'PostgreSQL, MySQL e SQLite: **relacionais**; MongoDB: **documentos (não relacional)**.', 'Nota cheia (0,2): os quatro corretos. Metade (0,1): um erro. Zero (0): dois ou mais erros.'),
      (v_atividade, 5, 2, 'Compare PostgreSQL e SQLite quanto ao uso típico e ao funcionamento (com ou sem servidor).', 0.4, '**PostgreSQL** roda como **servidor**, atende muitos usuários ao mesmo tempo e é usado em sistemas web e APIs. **SQLite** é um **arquivo** usado direto pela aplicação, **sem servidor**, ideal para apps de celular, protótipos e testes.', 'Nota cheia (0,4): uso típico + com/sem servidor dos dois. Metade (0,2): só um dos aspectos. Zero (0): descrições trocadas.'),
      (v_atividade, 5, 3, 'Explique em que situação o MongoDB seria considerado e o que o PostgreSQL oferece de parecido.', 0.4, 'MongoDB quando os dados têm **estrutura variável** (ex.: catálogo em que cada categoria tem campos diferentes). O PostgreSQL oferece **colunas JSON**, que também guardam dados de formato variável.', 'Nota cheia (0,4): situação + recurso JSON do PostgreSQL. Metade (0,2): só um dos dois. Zero (0): situação sem relação com estrutura variável.'),
      (v_atividade, 6, 1, 'Cite quatro requisitos que devem ser conferidos antes de instalar o gerenciador.', 0.2, 'Quatro entre: **sistema operacional** suportado (64 bits), **memória**, **processador**, **espaço em disco**, **rede/porta/firewall**, **versão compatível com o back-end**, **conhecimento da equipe**, **licença**.', 'Nota cheia (0,2): quatro corretos. Metade (0,1): dois ou três. Zero (0): um ou nenhum.'),
      (v_atividade, 6, 2, 'Explique os requisitos de rede, incluindo a porta padrão do PostgreSQL e o firewall.', 0.4, 'O PostgreSQL usa a **porta 5432**; ela deve estar **liberada no firewall** apenas para o **servidor da aplicação** (e para quem administra), e o servidor da aplicação precisa alcançar o servidor do banco pela rede.', 'Palavras-chave: 5432; firewall; acesso do servidor da aplicação. Nota cheia (0,4): porta + firewall + quem acessa. Metade (0,2): porta correta sem firewall, ou firewall sem porta. Zero (0): porta errada e sem explicação.'),
      (v_atividade, 6, 3, 'Explique por que o espaço em disco deve considerar mais do que os dados de hoje.', 0.4, 'Porque o disco precisa guardar também **índices**, **registros de transação/logs** e **backups**, além do **crescimento** dos dados ao longo do tempo.', 'Nota cheia (0,4): crescimento + pelo menos um item além dos dados (índices, logs, backups). Metade (0,2): só crescimento ou só backups. Zero (0): sem relação.'),
      (v_atividade, 7, 1, 'Diga a qual nível (externo, conceitual ou físico) pertence cada uma das três partes descritas.', 0.2, 'Secretaria vê nome e curso: **externo**; tabelas aluno, curso, matricula: **conceitual (lógico)**; arquivos e índices no disco: **físico**.', 'Nota cheia (0,2): os três corretos. Metade (0,1): dois corretos. Zero (0): um ou nenhum.'),
      (v_atividade, 7, 2, 'Explique o que o nível externo permite fazer com setores diferentes da escola.', 0.4, 'O nível externo cria **visões**: cada setor enxerga **só a parte dos dados de que precisa** (ex.: financeiro vê mensalidades, secretaria vê matrículas), sem mudar as tabelas e protegendo dados que o setor não deve ver.', 'Palavras-chave: visões; cada setor vê só o necessário; sem mudar as tabelas. Nota cheia (0,4): explicação + exemplo de setores. Metade (0,2): explicação sem exemplo. Zero (0): confunde com nível físico.'),
      (v_atividade, 7, 3, 'Explique a diferença entre o nível conceitual e o nível físico.', 0.4, 'O **conceitual** descreve **o que** existe no banco (tabelas, colunas, chaves e regras); o **físico** descreve **como** os dados são gravados (arquivos, páginas, índices no disco).', 'Nota cheia (0,4): diferença "o que × como" com exemplos. Metade (0,2): só um nível explicado. Zero (0): níveis trocados.'),
      (v_atividade, 8, 1, 'Diga qual mudança é exemplo de independência lógica e qual é de independência física.', 0.2, '(1) coluna telefone: **independência lógica**; (2) trocar de disco: **independência física**.', 'Nota cheia (0,2): as duas corretas. Metade (0,1): não se aplica (é tudo ou nada nesta). Zero (0): trocadas.'),
      (v_atividade, 8, 2, 'Explique o que a independência lógica garante às telas que não usam a coluna telefone.', 0.4, 'As telas que não usam a coluna telefone **continuam funcionando sem nenhuma alteração**, porque a mudança no nível conceitual não afeta as visões que não dependem dela.', 'Palavras-chave: telas continuam funcionando; sem alteração; nível conceitual. Nota cheia (0,4): garantia + motivo. Metade (0,2): só "não quebra". Zero (0): diz que todas as telas precisam ser refeitas.'),
      (v_atividade, 8, 3, 'Explique o que a independência física garante à aplicação quando o disco é trocado.', 0.4, 'A aplicação e as tabelas **não precisam mudar**: o SGBD cuida de onde e como os dados são gravados; a aplicação continua usando o mesmo SQL.', 'Nota cheia (0,4): aplicação/tabelas sem mudança + SGBD cuida do armazenamento. Metade (0,2): só uma parte. Zero (0): diz que a aplicação precisa ser reescrita.'),
      (v_atividade, 9, 1, 'Cite os três papéis em relação ao banco de dados.', 0.2, '**Usuário final**, **desenvolvedor** e **administrador de banco (DBA)**.', 'Nota cheia (0,2): os três. Metade (0,1): dois. Zero (0): um ou nenhum.'),
      (v_atividade, 9, 2, 'Explique o que faz o desenvolvedor e dê um exemplo de tarefa dele no banco.', 0.4, 'O desenvolvedor **modela os dados** e **escreve o SQL** usado pela aplicação. Exemplo: criar a tabela de clientes ou escrever a consulta que lista os pedidos do mês.', 'Nota cheia (0,4): função + exemplo. Metade (0,2): só a função ou só o exemplo. Zero (0): descreve tarefa do usuário final.'),
      (v_atividade, 9, 3, 'Explique três tarefas do administrador de banco (DBA) e por que elas são importantes.', 0.4, 'Três entre: **instalar e configurar** o SGBD, fazer **backup e restauração**, cuidar do **desempenho**, **controlar acessos** (usuários e permissões), monitorar o servidor. São importantes porque mantêm os dados **disponíveis, seguros e recuperáveis**.', 'Nota cheia (0,4): três tarefas + importância. Metade (0,2): duas tarefas ou três sem importância. Zero (0): tarefas de outro papel.'),
      (v_atividade, 10, 1, 'Liste os requisitos da cooperativa que influenciam a escolha.', 0.2, '**500 acessos simultâneos**, **pagamentos (transações)**, **orçamento baixo**, **equipe que conhece SQL** (sistema web).', 'Nota cheia (0,2): três ou quatro requisitos. Metade (0,1): dois. Zero (0): um ou nenhum.'),
      (v_atividade, 10, 2, 'Recomende um gerenciador e justifique com pelo menos dois requisitos.', 0.4, '**PostgreSQL** (ou MySQL/MariaDB): é **livre** (orçamento baixo), **relacional com SQL** (equipe já conhece), tem **transações ACID** (pagamentos) e suporta **muitos acessos** como servidor.', 'Nota cheia (0,4): gerenciador relacional servidor livre + dois requisitos. Metade (0,2): gerenciador adequado + um requisito. Zero (0): SQLite, planilha ou comercial caro sem justificativa coerente.'),
      (v_atividade, 10, 3, 'Explique por que o SQLite não seria a melhor escolha nesse caso.', 0.4, 'O SQLite é um **arquivo sem servidor**, pensado para **um aplicativo local**; não é adequado para **500 acessos simultâneos** de um sistema web com pagamentos, pois tem **concorrência limitada** para gravações ao mesmo tempo.', 'Palavras-chave: sem servidor/arquivo; acessos simultâneos; concorrência limitada. Nota cheia (0,4): motivo técnico ligado aos acessos. Metade (0,2): "é fraco" sem dizer por quê. Zero (0): diz que o SQLite não usa SQL ou não guarda dados.');
end $$;
